#!/usr/bin/env python3
"""Turn 35 Wave 42: SET-PIECE MASTERY - corner routines (footedness conflict, A-cross, tall targets, arrow technique, timing, behind-the-goalline, shortest-player trick, DLS25 header nerf), corner defence, free kicks (dual-taker rule, per-player curl, 70% power floor, the wall-as-reference, the switch-taker timing trick, short-pass alternative, distance bands), penalties (DLL vs shootout conversion, the techniques), plus Scenarios/Exhibition/challenge economics and the DLS26 Scenario update."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w42')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-444: set pieces ----------
e_sp=new_ev("r/DreamLeagueSoccer 1lyxfag (Jul 2025 corners), 1f1gi5l (Aug 2024 free kicks), 18mbe3b (Dec 2023 corner technique), 1pp7fzd (Dec 2025 corners easier than penalties), 1l8rmr5 (Jun 2025 free kicks), 1ap2595 (Feb 2024), 1abr36k (Jan 2024), 18a9fja (Dec 2023), 1nv6gxl (Oct 2025), 1ilktqr (Feb 2025), 1hg5ari (Dec 2024), 14ustvs (Dec 2023), 1jmtcwh (Mar 2025 shootouts), pztsbz, 1cvembm, mokoweb, LevelWinner DLS20/DLS24, dontruko",
    "SET-PIECE MASTERY. CORNERS ARE THE MOST RELIABLE GOAL SOURCE IN DLS26 - a December 2025 post states 'corners are way too easy to score now. If your opponent in DLL gets one, it's almost guaranteed that you concede.' FOOTEDNESS IS CONTESTED: the majority view is that a RIGHT-footed player takes the RIGHT corner and a LEFT-footed player takes the LEFT corner, which makes corners 'more accurate', while a minority reports the opposite. The widely agreed mechanics are: (a) use A to cross, because A passes are fast and easy to pinpoint players; (b) put TALL players in the box - Konate, Haaland and Van Dijk are named, and one source says you need 190+ players for the header routine to work; (c) take corners from BEHIND the goal line, not from next to the sideline; (d) use the SHORTEST players on corner duty so the players in the box are on average taller; (e) adjust the aim arrow so roughly 90% is inside the pitch and 10% outside, or set the aim line at about 30 degrees to the goal line; (f) TIMING IS CRITICAL - press A right before the ball reaches the target player. Alternative power recipes reported: A to 60%, A to 80-90% with inwards-then-outwards curve, C at 2/3-3/4, C at 80% on a 50-60 degree angle, or simply 'do not move the arrow, strong power lob to your defender, short header to nearest open man for tap in'. The outswinger routine (call a second player to pull a defender away and open space, set an outswinger with the matching foot, Max B, shoot) remains valid. DLS25 NERFED corner headers, so the fallback is to aim for the middle and press B to pass to someone better positioned rather than heading immediately. DEFENDING CORNERS: switch to a tall player and B-pass the ball 90 degrees away from the direction the opponent wants to head it; alternatively charge the A button and point up-field as soon as the corner is taken. FREE KICKS: pick TWO takers, one left-footed and one right-footed, and stick to them because technique becomes consistent. Every player has DIFFERENT free-kick settings - Ronaldo and Messi take them differently and the same technique will not work for both - and curl varies by player (Alexander-Arnold 'curves A LOT', Modric way less). Use AT LEAST 70% POWER, because anything below is not guaranteed to clear the wall. THE WALL IS THE REFERENCE: learn how much your taker curls depending on which player in the wall the arrow points at. Aim over the SHORTEST player in the wall and at the TOP corners, never the centre, with a diagonal swipe. Distance bands: 18-22 yards = curl shot with the inside foot; 23-28 yards = power shot or curled top-corner; 30+ yards = long-shot technique or pass. THE LIVE-MODE TIMING TRICK: an opponent can manually move a player onto the goal line and head your free kick away, so either shoot to the other side or take it quickly - the advanced version is to WAIT for them to step onto the line, then SWITCH THE TAKER (which resets where their player is) and shoot immediately. If struggling, do not take it directly: pass to a player near the wall with C and shoot from the resulting long shot, or cross into the box. PENALTIES: reported conversion is 85-90% in DLL and 70-80% in shootouts, and multiple players call shootout penalties 'rigged' with predictable run-ups. Techniques that work: a little left or right of the middle with moderate power; low C press on either side with a medium A; A little tap or full-power B to the bottom corners; for the AI, the middle with a slightly powered A (just enough to reach the keeper's head); and aiming one-third away from the keeper toward the post with the pass button held to half or two-thirds power. A universal warning: make the button taps as GENTLE AND QUICK AS POSSIBLE, because holding a split-second too long produces a wild, overpowered shot. Always aim for the top or bottom corners - the top of the goal gives an illusion of width that a wasted penalty will not honour.",
    "evidence/raw/turn35_w42/EV-444_set_pieces.html",
    "SET PIECES: corners are the most reliable goal source in DLS26 - 'if your opponent in DLL gets one, it's almost guaranteed you concede'. FOOTEDNESS CONTESTED (majority: same-foot corner, minority: opposite-foot). Agreed mechanics: use A to cross (fast, pinpoint); TALL players in the box (Konate/Haaland/VVD, 190+ needed); take corners from BEHIND the goal line not the sideline; use the SHORTEST players on corner duty so the box is taller; aim arrow ~90% inside the pitch; ~30 degrees to the goal line; TIMING - press A right before the ball reaches the target. Power recipes: A 60%, A 80-90% curve, C 2/3-3/4, C 80% at 50-60 degrees, or no arrow change with a strong lob and a short header to the nearest open man. DLS25 nerfed corner headers - fall back to aiming middle and pressing B to pass. Defending corners: tall player, B-pass 90 degrees from the header direction, or charge A and point up-field. FREE KICKS: two dedicated takers (one left, one right); every player has DIFFERENT free-kick settings (Ronaldo vs Messi, Arnold curls a lot, Modric less); use AT LEAST 70% POWER; THE WALL IS THE REFERENCE for curl; aim over the shortest player in the wall at the TOP corners with a diagonal swipe; distance bands 18-22yd curl / 23-28yd power or curled top-corner / 30+yd long shot or pass. LIVE TIMING TRICK: wait for the opponent to step onto the line, SWITCH THE TAKER to reset their player, then shoot immediately. If struggling, C-pass to a player near the wall and shoot the rebound, or cross. PENALTIES: 85-90% in DLL, 70-80% in shootouts, shootouts called rigged; techniques - slightly off-centre with moderate power, low C with medium A, A tap or full-power B to bottom corners, middle with slight power vs the AI, one-third off the keeper with pass at half to two-thirds power; taps must be GENTLE AND QUICK or the shot flies; always top or bottom corners",
    quality="community")

add_claim("Corners are the most reliable goal source in DLS26 - a December 2025 post states that if an opponent in Dream League Live gets a corner it is almost guaranteed you concede.", 3, "setpieces/corners-most-reliable", [e_sp])
add_claim("CONFLICT on corner footedness: the majority view is that a right-footed player takes the right corner and a left-footed player the left corner for better accuracy, while a minority reports the opposite pairing works better.", 3, "setpieces/corner-footedness-conflict", [e_sp], notes="C-022 candidate - test both in training")
